// Indexed by game::MobKind. The order here is the enum's order, and the
// static_assert in render.cpp is what keeps it that way.
struct MobArt {
  const uint8_t* pix;      // FRAMES * H * W
  const uint8_t (*pal)[3];
  uint8_t w, h, frames, colours;
  uint8_t walk;            // frames [0, walk) are the walk cycle;
                           // [walk, frames) are attack poses
  float   worldH;          // how tall it stands, in blocks
};

